/**
 * Cloudflare Worker entry point (`handler.ts`). Deploy with `wrangler deploy`
 * using `ts/wrangler.toml`; set the token with `wrangler secret put API_TOKEN`.
 *
 * Bindings:
 * - `CACHE_BUCKET` (R2): cobuild locks and cache (read only here), bisection
 *   sessions (read/write under `v1/<scope>/bisect/`);
 * - `ARTIFACTS` (Artifacts, optional): enables `/api/bisect` and the
 *   read-only `/api/artifacts` view. Its type is
 *   generated by `wrangler types`; this file declares only the part it uses.
 */
import { handle, type HandlerConfig } from "./handler.js"
import type { BisectDeps } from "./bisectRoutes.js"
import type { R2BucketLike } from "./r2Bucket.js"
import type { ArtifactsNamespaceLike } from "../bisect/artifactsApi.js"
import { makeR2SessionStore, type R2WritableBucketLike } from "./bisectStore.js"
import { isValidScope } from "../cache/scope.js"
import { Duration, type Redacted } from "../fx/index.js"
import { secretFromConfig } from "../secrets.js"

export interface Env {
  readonly CACHE_BUCKET: R2BucketLike & { readonly put?: R2WritableBucketLike["put"] }
  readonly ARTIFACTS?: ArtifactsNamespaceLike
  /** Read token: opens the GET views (locks, cache, artifacts). */
  readonly API_TOKEN: string
  /** Optional write token: required by every `/api/bisect` route when set (`handler.ts`, "Roles"). */
  readonly BISECT_API_TOKEN?: string
  readonly COBUILD_SCOPE?: string
  /** TTL in seconds of the read tokens minted for bisect runners (default 3600). */
  readonly BISECT_TOKEN_TTL_S?: string
}

const configError = (message: string): Response =>
  new Response(JSON.stringify({ error: "worker misconfigured", detail: message }), { status: 500, headers: { "content-type": "application/json" } })

/**
 * Check the Worker's configuration. Fails closed: there is no default scope
 * (a missing `COBUILD_SCOPE` must not expose or write the trusted scope),
 * an empty `API_TOKEN` is refused, and `BISECT_TOKEN_TTL_S` must be a
 * positive integer. The tokens are decoded into `Redacted` here (the
 * Worker's configuration decode layer) and unwrapped only for the
 * constant-time comparison in `roleOf`.
 */
export const workerConfig = (
  env: Env
): { scope: string; token: Redacted.Redacted<string>; writeToken?: Redacted.Redacted<string>; tokenTtl?: Duration.Duration } | string => {
  const scope = env.COBUILD_SCOPE
  if (scope === undefined || scope === "") return "COBUILD_SCOPE is not set (no default scope)"
  if (!isValidScope(scope)) return `COBUILD_SCOPE ${JSON.stringify(scope)} is not a valid scope`
  const token = secretFromConfig(env.API_TOKEN)
  if (token === undefined) return "API_TOKEN is not set"
  if (env.BISECT_API_TOKEN !== undefined && env.BISECT_API_TOKEN === env.API_TOKEN) return "BISECT_API_TOKEN must differ from API_TOKEN"
  const write = secretFromConfig(env.BISECT_API_TOKEN)
  const roles = write !== undefined ? { scope, token, writeToken: write } : { scope, token }
  if (env.BISECT_TOKEN_TTL_S === undefined) return roles
  const ttl = Number(env.BISECT_TOKEN_TTL_S)
  if (!Number.isSafeInteger(ttl) || ttl <= 0) return `BISECT_TOKEN_TTL_S expects a positive integer, got ${JSON.stringify(env.BISECT_TOKEN_TTL_S)}`
  return { ...roles, tokenTtl: Duration.seconds(ttl) }
}

/**
 * The handler configuration for a request, from the environment. `bisectExtra`
 * adds the routes the edge module (`../workers/edge.ts`) can serve because it
 * has the Workflow and Sandbox bindings (result / approve / reject / drive).
 */
export const handlerConfigFor = (env: Env, bisectExtra: Partial<BisectDeps> = {}): HandlerConfig | string => {
  const cfg = workerConfig(env)
  if (typeof cfg === "string") return cfg
  const { scope } = cfg
  const bucket = env.CACHE_BUCKET
  const put = bucket.put
  return {
    scope,
    token: cfg.token,
    ...(cfg.writeToken !== undefined ? { writeToken: cfg.writeToken } : {}),
    ...(env.ARTIFACTS !== undefined ? { artifacts: env.ARTIFACTS } : {}),
    // One JSON line per request; Workers Logs ([observability] in wrangler.toml) indexes the fields.
    log: (entry) => console.log(JSON.stringify(entry)),
    now: () => Date.now(),
    ...(env.ARTIFACTS !== undefined && put !== undefined
      ? {
          bisect: {
            artifacts: env.ARTIFACTS,
            store: makeR2SessionStore(writableBucket(env), scope),
            now: () => Date.now(),
            ...(cfg.tokenTtl !== undefined ? { tokenTtl: cfg.tokenTtl } : {}),
            ...bisectExtra
          }
        }
      : {})
  }
}

/** The bucket binding as the conditional-write shape (`get` + `put` with `onlyIf`). */
export const writableBucket = (env: Env): R2WritableBucketLike => {
  const bucket = env.CACHE_BUCKET
  const put = bucket.put
  if (put === undefined) throw new Error("CACHE_BUCKET binding has no put()")
  return { get: (k) => bucket.get(k), put: (k, v, o) => put.call(bucket, k, v, o) }
}

/** The `fetch` handler (also re-exported by the edge module). */
export const fetchHandler = (request: Request, env: Env, bisectExtra: Partial<BisectDeps> = {}): Promise<Response> => {
  const cfg = handlerConfigFor(env, bisectExtra)
  if (typeof cfg === "string") {
    console.error(JSON.stringify({ level: "error", msg: "worker misconfigured", detail: cfg }))
    return Promise.resolve(configError(cfg))
  }
  return handle(request, env.CACHE_BUCKET, cfg)
}

export default {
  fetch: (request: Request, env: Env): Promise<Response> => fetchHandler(request, env)
}
